mapper.select:
SELECT EXISTS(SELECT 1
              FROM user_relation
              WHERE user_id = #{userId}
                AND to_user_id = #{toUserId}
                AND status = 0) AS exist_flag

mapper.update:
UPDATE user_relation
SET status     = 1,
    updated_at = #{updatedAt}
WHERE user_id = #{userId}
  AND to_user_id = #{toUserId}
  AND status = 0 LIMIT 1;

mapper.select:
select user.avatar_url, user.username, user.id from `user` inner join ( select `to_user_id` from user_relation as ur
ur.user_id = #{userId} and ur.status = 0 order by `updated_at` limit #{pageNum}, #{pageSize}
) as ur_temp on `user`.id = ur_temp.`to_user_id`

select user.avatar_url, user.username, user.id from `user` inner join ( select `user_id` from user_relation as ur
ur.to_user_id = #{userId} and ur.status = 0 order by `updated_at` limit #{pageNum}, #{pageSize}
) as ur_temp on `user`.id = ur_temp.`user_id`
